```ts
// app/api/brief/route.ts
import Anthropic from '@anthropic-ai/sdk';

const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });

export async function POST(req: Request) {
  const { clientNotes } = await req.json();

  if (!clientNotes || typeof clientNotes !== 'string' || clientNotes.length > 8000) {
    return Response.json({ error: 'clientNotes is required and must be under 8000 characters' }, { status: 400 });
  }

  const message = await client.messages.create({
    model: 'claude-sonnet-4-5',        // fixed server-side — the browser can't choose
    max_tokens: 1024,                   // fixed server-side — the browser can't uncap it
    messages: [{ role: 'user', content: `Turn these client notes into a structured brief:\n${clientNotes}` }],
  });

  const textBlock = message.content.find(b => b.type === 'text');
  return Response.json({ brief: textBlock?.text ?? '' });   // briefdesk's own shape, not Anthropic's
}
```

Two things changed: the route only accepts `clientNotes`, validated before Claude is ever called, and it returns `{ brief: string }` — a shape briefdesk defines. The frontend now depends on a contract briefdesk controls, not on Anthropic's internal response structure, and `model`/`max_tokens` are fixed server-side where a browser has no way to override them.

The same shaping discipline applies to errors as to success responses — the frontend should get a stable, briefdesk-defined error shape, never Anthropic's raw exception forwarded as-is:

```ts
export async function POST(req: Request) {
  const { clientNotes } = await req.json();
  if (!clientNotes || typeof clientNotes !== 'string' || clientNotes.length > 8000) {
    return Response.json({ error: 'clientNotes is required and must be under 8000 characters' }, { status: 400 });
  }

  try {
    const message = await client.messages.create({
      model: 'claude-sonnet-4-5',
      max_tokens: 1024,
      messages: [{ role: 'user', content: `Turn these client notes into a structured brief:\n${clientNotes}` }],
    });
    const textBlock = message.content.find(b => b.type === 'text');
    return Response.json({ brief: textBlock?.text ?? '' });
  } catch (err) {
    console.error('Claude call failed:', err);  // the real detail goes to server logs
    return Response.json({ error: 'Could not generate a brief right now. Try again in a moment.' }, { status: 502 });
  }
}
```

The raw error still goes somewhere — `console.error` on the server, visible in logs for debugging — but the browser gets a plain-language message it can actually show a user, on a status code (`502`, meaning the upstream service failed) that a frontend can branch on without parsing Anthropic-specific error text. This is the same instinct the CLI-tools phase taught for error messages aimed at whoever's actually reading them: a stack trace or a raw provider error answers a developer's questions, not a user's.

The Anthropic SDK's `.stream()` method, combined with a Route Handler returning a `ReadableStream`, forwards each chunk as it arrives over Server-Sent Events:

```ts
// app/api/brief/route.ts — streaming version
export async function POST(req: Request) {
  const { clientNotes } = await req.json();
  if (!clientNotes) return Response.json({ error: 'clientNotes is required' }, { status: 400 });

  const encoder = new TextEncoder();
  const stream = new ReadableStream({
    async start(controller) {
      const claudeStream = client.messages.stream({
        model: 'claude-sonnet-4-5',
        max_tokens: 1024,
        messages: [{ role: 'user', content: `Turn these client notes into a structured brief:\n${clientNotes}` }],
      });

      claudeStream.on('text', (chunk) => {
        controller.enqueue(encoder.encode(`data: ${JSON.stringify({ text: chunk })}\n\n`));
      });
      claudeStream.on('end', () => {
        controller.enqueue(encoder.encode('data: [DONE]\n\n'));
        controller.close();
      });
      claudeStream.on('error', (err) => {
        controller.enqueue(encoder.encode(`data: ${JSON.stringify({ error: 'stream failed' })}\n\n`));
        controller.close();
      });
    },
  });

  return new Response(stream, {
    headers: { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive' },
  });
}
```

Each `text` event from the Anthropic stream becomes one SSE `data:` line, sent to the browser the moment it's generated — not batched, not buffered until the end.

