contentSections.body:
Treating loading as a first-class state means giving it its own explicit branch, not letting it fall out of whatever the empty-array default happens to render:

```tsx
function BriefList() {
  const [status, setStatus] = useState<'loading' | 'empty' | 'loaded'>('loading');
  const [briefs, setBriefs] = useState<Brief[]>([]);

  useEffect(() => {
    fetch('/api/briefs')
      .then(r => r.json())
      .then((data: Brief[]) => {
        setBriefs(data);
        setStatus(data.length === 0 ? 'empty' : 'loaded');
      });
  }, []);

  if (status === 'loading') return <BriefListSkeleton />;
  if (status === 'empty') return <EmptyBriefsState />;
  return <ul>{briefs.map(b => <BriefCard key={b.id} brief={b} />)}</ul>;
}
```

Now there are three genuinely different screens instead of one screen with a gap in it: a loading placeholder that says something's coming, an empty state that says there's nothing yet (and what to do about it), and the real list. Each one was designed on purpose, not left as whatever an empty array happens to render.

Designing the empty state means asking *why* before writing the copy:

```tsx
function BriefListArea({ briefs, hasActiveFilter }: BriefListAreaProps) {
  if (briefs.length > 0) return <ul>{briefs.map(b => <BriefCard key={b.id} brief={b} />)}</ul>;

  if (hasActiveFilter) {
    return (
      <EmptyState
        title="No briefs match your search"
        body="Try a different term, or clear your filters to see everything."
        action={{ label: 'Clear filters', onClick: clearFilters }}
      />
    );
  }

  return (
    <EmptyState
      title="No briefs yet"
      body="Generate your first one from a client's notes — it takes about a minute."
      action={{ label: 'Generate a brief', href: '/new' }}
    />
  );
}
```

One shared `EmptyState` component, two genuinely different messages, each pointing at the actual next step for that situation. The visible layout (an icon, a heading, a body line, one button) stays consistent — it's the design system's job to make that reusable — but the words and the action change with the cause.

